SELECT json_object('obs','resource','declined',CASE WHEN (SELECT count(*) FROM resources WHERE doc_id=1 AND resource_id=1)=0 THEN 1 ELSE 0 END,'value_kind','json','value',json_object('path',(SELECT path FROM resources WHERE doc_id=1 AND resource_id=1),'member_bytes',(SELECT member_bytes FROM resources WHERE doc_id=1 AND resource_id=1),'member_sha256',(SELECT member_sha256 FROM resources WHERE doc_id=1 AND resource_id=1)),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','resource','ordinal',0),'provenance',NULL,'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',json_object('family_id',(SELECT family_id FROM revisions WHERE doc_id=1),'member_id',(SELECT member_id FROM revisions WHERE doc_id=1),'is_head',(SELECT is_head FROM revisions WHERE doc_id=1)))